WITH valid AS (SELECT *, LENGTH(event_type) AS event_type_length, CEIL(duration_sec) AS duration_sec_whole FROM web_events WHERE event_time > TIMESTAMP '2023-08-05 01:00:00' AND page IS NOT NULL) SELECT session_id, DATE_TRUNC('WEEK', event_time) AS week_start, page, MAX(event_time) AS last_seen, ROUND(AVG(duration_sec_whole), 2) AS avg_duration_sec_whole, COUNT(CASE WHEN page = '/search' THEN 1 END) AS search_count, SIZE(COLLECT_SET(event_type)) AS num_event_types, COUNT_IF(page = '/cart') AS cart_events, APPROX_PERCENTILE(duration_sec_whole, 0.9) AS duration_sec_whole_p90 FROM valid GROUP BY session_id, DATE_TRUNC('WEEK', event_time), page ORDER BY cart_events DESC;
